using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // and DateTime.UtcNow is non-deterministic (causes migration diffs every run).
        // Use a fixed seed date instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: Cosmos provider now uses "$type" for the
            // discriminator property by default instead of "Discriminator".
            // For existing documents that already use "Discriminator", you must
            // explicitly configure it to preserve backward compatibility.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// --- Cosmos query service demonstrating sync → async migration ---
// EF Core 9 breaking change: Synchronous I/O with the Cosmos provider now throws
// by default. All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — synchronous, now throws InvalidOperationException in EF Core 9):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();
    //
    // AFTER (EF Core 9 — must use async):
    public async Task<List<Product>> GetByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }
}

